 $sources=[];foreach(($search['results']??[]) as $s){$url=(string)($s['url']??'');if($url==='')continue;$sources[]=['title'=>substr((string)($s['title']??'Web source'),0,250),'url'=>$url,'content'=>substr((string)($s['content']??''),0,1100),'accessed'=>gmdate('Y-m-d')];}
